diff --git a/src/emu/cpu/include/cpu/aot/aot_runtime.h b/src/emu/cpu/include/cpu/aot/aot_runtime.h
index 907e1e5a1..fc5bae1fa 100644
--- a/src/emu/cpu/include/cpu/aot/aot_runtime.h
+++ b/src/emu/cpu/include/cpu/aot/aot_runtime.h
@@ -33,6 +33,9 @@ namespace eka2l1::arm::aot {
     // Compile deferred scalar/span misses through the existing memory helpers.
     // Frozen before initialization; disabled until coverage and timing acceptance.
     inline bool compiled_memory_misses = false;
+    // Frozen before init: 0 sampled, 1 first-use ROM/RAM, 2 first-use RAM.
+    // Mode 2 retains ROM hotness filtering to avoid filling its bounded cache.
+    inline unsigned synchronous_compilation = 0;
     inline constexpr std::uint32_t svc_pending = 0x80000000u;
     inline constexpr std::uint32_t svc_taken = 0x40000000u;
     inline constexpr std::uint32_t svc_page_end = 0x20000000u;
diff --git a/src/emu/cpu/src/aot/aot_runtime.cpp b/src/emu/cpu/src/aot/aot_runtime.cpp
index bed377f61..d00515ad1 100644
--- a/src/emu/cpu/src/aot/aot_runtime.cpp
+++ b/src/emu/cpu/src/aot/aot_runtime.cpp
@@ -441,9 +441,13 @@ std::uint32_t execute_single(ARMul_State *cpu, aot_func function) {

 void observe_hot_pc(ARMul_State *cpu) {
 #ifdef __EMSCRIPTEN__
-    if (!hot_compilation_enabled || validation_running || (++hot_dispatches & 31)) return;
-    if ((hot_dispatches & 8191) == 0) flush_hot_blocks();
+    if (!hot_compilation_enabled || validation_running) return;
     const auto pc = cpu->Reg[15], key = pc | cpu->TFlag;
+    const bool first_use = synchronous_compilation == 1
+        || (synchronous_compilation == 2 && (pc < hot_rom_base || pc - hot_rom_base >= hot_rom_size));
+    ++hot_dispatches;
+    if (!first_use && (hot_dispatches & 31)) return;
+    if (first_use || (hot_dispatches & 8191) == 0) flush_hot_blocks();
     if (pc < hot_rom_base || pc - hot_rom_base >= hot_rom_size) {
         if (!ram_compilation_enabled || !cpu->parent()->resolve_code) return;
         if (ram_cache.versions() >= 16384) {
@@ -456,7 +460,7 @@ void observe_hot_pc(ARMul_State *cpu) {
         const auto identity = validated_code_cache::key(view.address_space, key);
         if (ram_counts.size() >= 131072 && !ram_counts.count(identity)) return;
         auto &count = ram_counts[identity];
-        if (++count % 8) {
+        if (++count % 8 && !first_use) {
             if ((common::guest_profile::enabled && common::performance::counting())) common::guest_profile::state.event("candidate_threshold",key,view.address_space);
             return;
         }
@@ -501,13 +505,15 @@ void observe_hot_pc(ARMul_State *cpu) {
         tr.func.export_name = "r_" + std::to_string(entry.version) + "_pc_" + std::to_string(pc);
         hot_pending.push_back(std::move(tr.func));
         if (common::performance::counting()) ++common::performance::ram_blocks_compiled;
-        if (hot_pending.size() >= 32) flush_hot_blocks();
+        if (first_use || hot_pending.size() >= 32) flush_hot_blocks();
         return;
     }
     if (hot_compiled >= 4096) return;
     if (hot_counts.size() >= 65536 && !hot_counts.count(key)) return;
     auto &count = hot_counts[key];
-    if (count >= 8 || ++count != 8) return; // one attempt per immutable entry
+    if (count >= 8) return; // one attempt per immutable entry
+    if (first_use) count = 8;
+    else if (++count != 8) return;
     const auto offset = pc - hot_rom_base;
     const auto size = std::min(chaining_enabled ? primary_window_bytes : 128u, hot_rom_size - offset);
     leaf_resolver leaves = [](std::uint32_t target) {
@@ -518,7 +524,7 @@ void observe_hot_pc(ARMul_State *cpu) {
     if (tr.func.body.empty() || !tr.entry_supported) return;
     tr.func.export_name = "f_" + std::to_string(key);
     hot_pending.push_back(std::move(tr.func));
-    if (hot_pending.size() >= 32) flush_hot_blocks();
+    if (first_use || hot_pending.size() >= 32) flush_hot_blocks();
     ++hot_compiled;
 #endif
 }
diff --git a/src/emu/cpu/src/aot/thumb_translator.cpp b/src/emu/cpu/src/aot/thumb_translator.cpp
index 9af07bbc3..d311d911f 100644
--- a/src/emu/cpu/src/aot/thumb_translator.cpp
+++ b/src/emu/cpu/src/aot/thumb_translator.cpp
@@ -3860,7 +3860,9 @@ namespace eka2l1::arm::aot {
                 w.i32_const(1); w.op(op_i32_and); w.set_local(TMP2);
                 w.store_i32(S::TFLAG, TMP2);
                 w.load_reg(14);
-                w.i32_const(~1);
+                // Align the outgoing PC before a short-budget return too.
+                w.get_local(TMP2); w.i32_const(1); w.op(op_i32_shl);
+                w.i32_const(~3); w.op(op_i32_or);
                 w.op(op_i32_and);
                 w.set_local(TMP1);
                 w.store_reg(15, TMP1);
@@ -3879,7 +3881,12 @@ namespace eka2l1::arm::aot {
                 // BX Rm / BLX Rm
                 int rm = (insn >> 3) & 0xF;
                 bool is_blx = (insn & 0x80) != 0;
-                w.load_reg(rm); w.set_local(TMP3); // capture before BLX overwrites LR
+                // BX PC reads the Thumb pipeline value, not the current
+                // instruction address stored in the runtime. BLX PC retains
+                // DynCom's raw-PC behavior for that unpredictable encoding.
+                if (rm == 15 && !is_blx) w.i32_const(insn_addr + 4);
+                else w.load_reg(rm);
+                w.set_local(TMP3); // capture before BLX overwrites LR
                 if (is_blx) {
                     // BLX Rm — set LR = next instruction | 1 (Thumb)
                     w.store_i32_const(S::LR, static_cast<std::int32_t>((insn_addr + 2) | 1));
@@ -3893,7 +3900,9 @@ namespace eka2l1::arm::aot {
                 w.i32_const(1); w.op(op_i32_and); w.set_local(TMP2);
                 w.store_i32(S::TFLAG, TMP2);
                 w.get_local(TMP3);
-                w.i32_const(~1);
+                // Align the outgoing PC before a short-budget return too.
+                w.get_local(TMP2); w.i32_const(1); w.op(op_i32_shl);
+                w.i32_const(~3); w.op(op_i32_or);
                 w.op(op_i32_and);
                 w.set_local(TMP1);
                 w.store_reg(15, TMP1);
diff --git a/src/emu/cpu/src/dyncom/arm_dyncom_interpreter.cpp b/src/emu/cpu/src/dyncom/arm_dyncom_interpreter.cpp
index 10a23e0d8..a28fdb1e4 100644
--- a/src/emu/cpu/src/dyncom/arm_dyncom_interpreter.cpp
+++ b/src/emu/cpu/src/dyncom/arm_dyncom_interpreter.cpp
@@ -2800,9 +2800,13 @@ AOT_RESUME:
     // Check if an AOT-compiled function exists for this PC
     {
         auto aot_func = num_instrs >= cpu->NumInstrsToExecute ? nullptr : eka2l1::arm::aot::lookup_compiled(cpu);
-        if (!aot_func && eka2l1::arm::aot::hot_compilation_enabled && !eka2l1::arm::aot::validation_running) {
+        if (!aot_func && eka2l1::arm::aot::hot_compilation_enabled && !eka2l1::arm::aot::validation_running
+                && (!eka2l1::arm::aot::synchronous_compilation || num_instrs < cpu->NumInstrsToExecute)) {
             eka2l1::arm::aot::observe_hot_pc(cpu);
-            // Newly compiled entries can be picked up on the next dispatch.
+            // The opt-in first-use policy installs before this instruction.
+            // Retry the normal validated lookup once; rejection still falls back.
+            if (eka2l1::arm::aot::synchronous_compilation)
+                aot_func = eka2l1::arm::aot::lookup_compiled(cpu);
         }
         if (aot_func) {
             link = nullptr; // An interpreted predecessor cannot link across compiled execution.
diff --git a/src/emu/wasm/main.cpp b/src/emu/wasm/main.cpp
